OVERTIME.conversion:
// EA s.38(4), (6) and Fourth Schedule: a monthly rate's hourly basic rate is 12 × monthly ÷ (52 × 44) whatever the contract's week; a daily rate's is the day ÷ its hours
const terms = ctx.subject.employment.terms;
const normal = Number(terms.normal_hours_per_day);
const monthly = get(terms, 'rate.unit', 'MONTHLY') === 'MONTHLY';
const hourly = monthly
	? (ctx.month_wage * 12) / (ctx.lookup.weeks_per_year * ctx.lookup.full_time_weekly_hours)
	: ctx.hour_rate;
const category = get(terms, 'statutory_work_category', 'NON_MANUAL');
const capped = category === 'NON_MANUAL' ? Math.min(hourly, ctx.lookup.non_workman_hourly_cap) : hourly;
// the employer's own overtime hour stands where it pays more than the Fourth Schedule
const methods = get(ctx.subject.employer, 'pay_methods', {});
const hour = monthly && get(methods, 'overtime_hour_basis', 'STATUTORY') !== 'STATUTORY' ? Math.max(ctx.hour_rate, capped) : capped;
// EA s.37(2)(c)(ii), (3)(c)(ii): a rest day's normal hours are rest-day pay; the hours past them are overtime, at the employer's rest-day multiple where it pays more
const multiple = Number(get(methods, 'rest_day_hourly_multiplier', 0));
return sum(
	get(ctx, 'work.days', []).map((day) => {
		if (get(day, 'day_type', 'WORK') !== 'REST') return Number(get(day, 'overtime_hours', 0)) * hour * ctx.lookup.multiplier;
		const past = Math.max(0, Number(get(day, 'worked_hours', 0)) - normal);
		return Math.max(past * hour * ctx.lookup.multiplier, past * multiple * ctx.hour_rate);
	})
);

PART_TIME_EXTRA_HOURS.conversion:
// Part-Time Regulations: hourly basic rate on the contract's own week; hours to the full-time day at 1×, past it at 1.5×
const employment = ctx.subject.employment;
const terms = employment.terms;
const normal = Number(terms.normal_hours_per_day);
const full = Number(get(employment, 'employee_extension_data.comparable_full_time_hours_per_day', 8));
const tier = Math.max(0, full - normal);
const hours = sum(
	get(ctx, 'work.days', [])
		.filter((day) => (get(day, 'day_type', 'WORK') === 'REST') === ctx.lookup.rest_day)
		.map((day) => {
			const beyond = ctx.lookup.rest_day
				? Math.max(0, Number(get(day, 'worked_hours', 0)) - normal)
				: Number(get(day, 'overtime_hours', 0));
			return ctx.lookup.past_full_time ? Math.max(0, beyond - tier) : Math.min(beyond, tier);
		})
);
// on a rest day, the employer's rest-day multiple stands where it pays more
const multiple = ctx.lookup.rest_day ? Number(get(ctx.subject.employer, 'pay_methods.rest_day_hourly_multiplier', 0)) : 0;
return hours * ctx.hour_rate * Math.max(ctx.lookup.multiplier, multiple);

