REST_DAY_WORK.conversion:
// EA s.37(3), at the employer's request: one day's basic pay up to half the normal hours, two above half; the employer's rest-day multiple stands on each day it pays more
const normal = Number(ctx.subject.employment.terms.normal_hours_per_day);
const worked = (day) => Number(get(day, 'worked_hours', 0));
const rest = get(ctx, 'work.days', []).filter((day) => get(day, 'day_type', 'WORK') === 'REST' && worked(day) > 0);
const owed = (day) =>
	worked(day) <= normal / ctx.lookup.half_day_divisor
		? ctx.lookup.employer_request_days_up_to_half
		: ctx.lookup.employer_request_days_above_half;
const multiple = Number(get(ctx.subject.employer, 'pay_methods.rest_day_hourly_multiplier', 0));
if (multiple <= 0) return sum(rest.map(owed)) * ctx.day_rate;
return sum(rest.map((day) => Math.max(owed(day) * ctx.day_rate, Math.min(worked(day), normal) * multiple * ctx.hour_rate)));

