// EA s.88(4): an extra day's salary at the basic rate; the salary already holds the day itself, and a holiday on a rest day moves to the next working day
const worked = get(ctx, 'work.days', []).filter((day) => {
	if (get(day, 'day_type', 'WORK') === 'REST') return false;
	const kind = get(day, 'holiday_kind', '');
	if (kind === '' || kind === 'MAKEUP_WORKDAY') return false;
	return Number(get(day, 'worked_hours', 0)) > 0;
});
return worked.length * ctx.lookup.holiday_work_days * ctx.day_rate;

CPF_AW.eligibility:
const facts = ctx.subject.employment.employee_extension_data;
if (Number(get(ctx, 'subtotals.ADDITIONAL_WAGES', 0)) === 0) return false;
const approved =
	get(facts, 'student_training_class', 'NONE') === 'LOCAL_APPROVED_TRAINING' &&
	get(facts, 'student_training_approved', false) === true &&
	get(facts, 'student_training_moe_subsidised', false) === true &&
	get(facts, 'student_training_evidence', '') !== '';
if (approved) return false;
return ['CITIZEN', 'PERMANENT_RESIDENT'].includes(
	get(ctx.subject.employment.terms, 'residency_status', '')
);

CPF_AW.employer_amount:
// CPF Act First Schedule: additional wages attract CPF up to the AW ceiling, the annual limit less the year's OW that attracted CPF, each month's OW at its own ceiling.
// CPF Board: at each AW payment estimate the year's OW from this month's; in the last month of the year or of the employment settle on the actual OW.
const terms = ctx.subject.employment.terms;
const from = ctx.run.salary_coverage.from;
const year = String(from).slice(0, 4);
const held = get(ctx, 'balances.month', {});
const paidMonth = String(get(ctx.run, 'pay_date', from)).slice(0, 7);
const heldIn = (paid, code) => (Object.hasOwn(held, paid + '.' + code) ? Number(held[paid + '.' + code]) : 0);
const wholeMonth =
	String(from) === String(month_start(from)) && String(ctx.run.salary_coverage.to) === String(month_end(from));
const separate = get(ctx.run, 'kind', '') !== 'OFF_CYCLE' && wholeMonth && heldIn(paidMonth, 'BASIC') > 0;
const before = (code) => (separate ? 0 : heldIn(paidMonth, code));
const earlierOrdinary = before('ORDINARY_WAGES');
const ordinary = Math.min(
	Number(get(ctx, 'subtotals.ORDINARY_WAGES', 0)) + earlierOrdinary,
	ctx.lookup.ordinary_ceiling
);
// Ahead of the month's salary an off-cycle run sits on last month's OW, or the contract's before any is paid.
const lastOrdinary = heldIn(String(add_months(paidMonth + '-01', -1)).slice(0, 7), 'ORDINARY_WAGES');
const under =
	get(ctx.run, 'kind', '') === 'OFF_CYCLE' && ordinary === 0
		? Math.min(lastOrdinary > 0 ? lastOrdinary : ctx.month_wage, ctx.lookup.ordinary_ceiling)
		: 0;
const monthAdditional =
	Math.max(0, before('ADDITIONAL_WAGES') - earlierOrdinary) +
	Math.max(
		0,
		Number(get(ctx, 'subtotals.ADDITIONAL_WAGES', 0)) -
			Number(get(ctx, 'subtotals.ORDINARY_WAGES', 0))
	);
const leaving = String(get(ctx.subject.employment, 'effective_range.to', ''));
const last = leaving.slice(0, 4) === year ? Number(leaving.slice(5, 7)) : 12;
const month = Number(String(from).slice(5, 7));
const earlier = (suffix) =>
	Object.keys(held).filter(
		(code) => code.startsWith(year + '-') && code.endsWith(suffix) && !code.startsWith(paidMonth + '.')
	);
const ordinaryBefore = earlier('.ORDINARY_WAGES').reduce(
	(total, code) => total + Math.min(Number(held[code]), ctx.lookup.ordinary_ceiling),
	0
);
const attracted = earlier('.CPF_AW.employer').reduce((total, code) => total + Number(held[code]), 0);
const paidEarlier = earlier('.ADDITIONAL_WAGES').reduce(
	(total, code) => total + Math.max(0, Number(held[code]) - heldIn(code.slice(0, 7), 'ORDINARY_WAGES')),
	0
);
const room = Math.max(
	0,
	ctx.lookup.annual_ceiling - ordinaryBefore - (ordinary + under) * Math.max(1, last - month + 1) - attracted
);
const pending = month === last ? paidEarlier - attracted + monthAdditional : monthAdditional;
return Math.max(0, Math.min(pending, room) - before('CPF_AW.employer'));

