CPF.employee_amount:
const terms = ctx.subject.employment.terms;
const facts = ctx.subject.employment.employee_extension_data;
const status = get(terms, 'residency_status', '');
if (!['CITIZEN', 'PERMANENT_RESIDENT'].includes(status)) return 0;
const dob = get(ctx.subject.employment.payroll, 'date_of_birth', '');
if (dob === '') return 0;
const age = age_on(dob, add_days(month_start(ctx.run.salary_coverage.from), -1));
const elections = get(facts, 'statutory.CPF', {});
const full = get(elections, 'spr_full_rates', false) === true;
const employerFull = get(elections, 'spr_employer_full_rates', false) === true;
const since = get(facts, 'residency_since', '');
const from = ctx.run.salary_coverage.from;
let phase = 'full';
if (status === 'PERMANENT_RESIDENT' && !full && since !== '') {
	if (from <= String(month_end(add_years(since, 1)))) phase = employerFull ? 'first_year_full_employer' : 'first_year';
	else if (from <= String(month_end(add_years(since, 2)))) phase = employerFull ? 'second_year_full_employer' : 'second_year';
}
const bands = ctx.lookup.cpf_bands.filter((band) => band.phase === phase);
let key = bands[0].key;
for (const band of bands) if (age >= band.age) key = band.key;
const midRate = get(ctx.lookup.cpf_rates, key + '_mid', 0);
const highRate = get(ctx.lookup.cpf_rates, key + '_high', 0);
const year = String(ctx.run.salary_coverage.from).slice(0, 4);
const held = get(ctx, 'balances.month', {});
const paidMonth = String(get(ctx.run, 'pay_date', from)).slice(0, 7);
const heldIn = (paid, code) => (Object.hasOwn(held, paid + '.' + code) ? Number(held[paid + '.' + code]) : 0);
const wholeMonth =
	String(from) === String(month_start(from)) && String(ctx.run.salary_coverage.to) === String(month_end(from));
const separate = get(ctx.run, 'kind', '') !== 'OFF_CYCLE' && wholeMonth && heldIn(paidMonth, 'BASIC') > 0;
const before = (code) => (separate ? 0 : heldIn(paidMonth, code));
const earlierOrdinary = before('ORDINARY_WAGES');
const ordinary = Math.min(
	Number(get(ctx, 'subtotals.ORDINARY_WAGES', 0)) + earlierOrdinary,
	ctx.lookup.ordinary_ceiling
);
// Ahead of the month's salary an off-cycle run sits on last month's OW, or the contract's before any is paid.
const lastOrdinary = heldIn(String(add_months(paidMonth + '-01', -1)).slice(0, 7), 'ORDINARY_WAGES');
const under =
	get(ctx.run, 'kind', '') === 'OFF_CYCLE' && ordinary === 0
		? Math.min(lastOrdinary > 0 ? lastOrdinary : ctx.month_wage, ctx.lookup.ordinary_ceiling)
		: 0;
// The AW that attracted CPF is on record; the last month of the year or of the employment settles it on the actual OW.
const leaving = String(get(ctx.subject.employment, 'effective_range.to', ''));
const last = leaving.slice(0, 4) === year ? Number(leaving.slice(5, 7)) : 12;
const earlier = (suffix) =>
	Object.keys(held).filter(
		(code) => code.startsWith(year + '-') && code.endsWith(suffix) && !code.startsWith(paidMonth + '.')
	);
const ordinaryBefore = earlier('.ORDINARY_WAGES').reduce(
	(total, code) => total + Math.min(Number(held[code]), ctx.lookup.ordinary_ceiling),
	0
);
const attracted = earlier('.CPF_AW.employer').reduce((total, code) => total + Number(held[code]), 0);
const excess =
	Number(String(from).slice(5, 7)) === last
		? Math.max(0, attracted - Math.max(0, ctx.lookup.annual_ceiling - ordinaryBefore - ordinary - under))
		: 0;
const additional = before('CPF_AW.employer') + Number(get(ctx, 'statutory.CPF_AW.employer', 0));
const owed = (wage) => {
	if (wage <= ctx.lookup.employee_threshold) return 0;
	if (wage <= ctx.lookup.full_rate_threshold)
		return round(
			midRate * (wage - ctx.lookup.employee_threshold),
			ctx.lookup.rounding_step,
			ctx.lookup.employee_rounding
		);
	return round(wage * highRate, ctx.lookup.rounding_step, ctx.lookup.employee_rounding);
};
return owed(ordinary + under + additional) - owed(under) - before('CPF.employee') - round(excess * highRate, ctx.lookup.rounding_step, ctx.lookup.employee_rounding);

CPF.employer_amount:
const terms = ctx.subject.employment.terms;
const facts = ctx.subject.employment.employee_extension_data;
