SDL_REMITTANCE.effects:
const run = ctx.entry;
const holidays = get(ctx, 'reads.holiday', []).map((h) => h.date);
const dueOn = add_working_days(add_days(month_end(run.salary_coverage.to), ctx.lookup.offset_days - 1), 1, holidays, [0, 6]);
// CPF Board: add each employee's levy, then round the sum down to a whole dollar
const levies = get(ctx, 'reads.payslip', []).flatMap((slip) => {
	if (!get(slip, 'breakdown.statutory', []).some((scheme) => scheme.code === 'SDL')) return [];
	const wage = get(slip, 'breakdown.checkpoints', []).find((row) => row.code === 'ADDITIONAL_WAGES');
	return [clamp(Number(get(wage, 'value', 0)) * ctx.lookup.sdl_rate, ctx.lookup.sdl_minimum, ctx.lookup.sdl_maximum)];
});
return [{
	entity_id: run.entity_id,
	title: ctx.lookup.title + ': $' + round(sum(levies), 1, 'DOWN').toFixed(0),
	due_on: dueOn,
	occurrence_key: 'SG:SDL_REMITTANCE:' + run.id
}];

