REEMPLOYMENT_OFFER.effects:
// Retirement and Re-employment Act s.7A: checked at every run, so the offer is raised from the run on or after the notice date.
const contract = ctx.subject.employment;
const day = String(first(ctx.reads.payroll_run).pay_date);
const born = contract.payroll.date_of_birth;
const years = born >= ctx.lookup.effective_date ? ctx.lookup.revised_age : ctx.lookup.prior_age;
const retirement = add_years(born, years);
if (day < add_months(retirement, -ctx.lookup.advance_months) || day > retirement) return [];
const key = 'SG:REEMPLOYMENT_OFFER:' + contract.id + ':' + retirement;
if (ctx.reads.obligation.some((task) => task.occurrence_key === key)) return [];
return [{
	entity_id: contract.entity_id,
	employee_id: contract.employee_id,
	employment_id: contract.id,
	title: ctx.lookup.title,
	due_on: add_months(retirement, -ctx.lookup.offer_months),
	occurrence_key: key
}];

