DEDUCTION_LIMIT.condition:
const row = ctx.entry;
// EA s.32(2): the limit does not apply to the last salary on termination
const leaving = get(ctx.subject, 'employment.effective_range.to', null);
if (leaving != null && leaving <= month_end(String(ctx.entry.period).slice(0, 7) + '-01')) return false;
// EA s.32(1) leaves out only s.27(1)(a), (f) and (j): the CPF employee share under (h) counts
const lines = get(ctx.entry, 'breakdown.lines', []);
const excluded = sum(lines.filter((line) => ctx.lookup.excluded_codes.includes(line.code)).map((line) => line.amount));
if (Number(row.total_deductions) - excluded <= ctx.lookup.share * Number(row.gross_earnings)) return false;
return get(ctx, 'reads.obligation', []).length === 0;

