PWM_WAGE_FLOOR.condition:
const employment = ctx.subject.employment;
const role = get(ctx.lookup.pwm_roles, String(get(employment, 'employee_extension_data.pwm_role', '')), null);
if (role === null) return false;
// MOM: the Progressive Wage requirements cover citizens and permanent residents
if (!ctx.lookup.local_residencies.includes(get(employment, 'terms.residency_status', ''))) return false;
const from = String(ctx.entry.period).slice(0, 7) + '-01';
const to = month_end(from);
const range = ctx.subject.employment.effective_range;
// a month worked in part is no test of a monthly figure
if (range.from > from) return false;
const leaving = get(range, 'to', null);
if (leaving != null && leaving < to) return false;
const lines = get(ctx.entry, 'breakdown.lines', []);
// MOM: a gross floor counts basic pay, allowances and productivity pay, never overtime or bonuses
const overtime = sum(lines.filter((line) => line.source === 'overtime_catalog').map((line) => line.amount));
const wage = role.base === 'BASIC' ? Number(ctx.entry.basic_earnings) : Number(ctx.entry.ordinary_wages) - overtime;
// steps are newest first: the first one already started replaces the role's floor
const step = get(role, 'steps', []).find((row) => row.from <= to);
const floor = Number(get(step ?? role, 'monthly_floor', 0));
// MOM: under 35 hours a week the floor is pro-rated on a 44-hour week
const hours = Number(get(employment, 'terms.normal_hours_per_week', ctx.lookup.full_time_weekly_hours));
const due = hours < ctx.lookup.full_time_minimum_hours ? (floor * hours) / ctx.lookup.full_time_weekly_hours : floor;
if (wage >= due) return false;
return get(ctx, 'reads.obligation', []).length === 0;

