WEEKLY_REST_DAY.condition:
const terms = get(ctx.subject, 'employment.terms', {});
const category = get(terms, 'statutory_work_category', '');
if (!ctx.lookup.statutory_work_categories.includes(category)) return false;
const ceiling = category === 'NON_MANUAL' ? ctx.lookup.nonmanual_monthly_ceiling : ctx.lookup.manual_monthly_ceiling;
if (!(Number(get(terms, 'rate.amount', 0)) <= ceiling)) return false;
if (!ctx.lookup.covered_engagements.includes(get(ctx.subject, 'employment.engagement', ''))) return false;
const dates = get(ctx, 'reads.roster_entry', [])
	.filter((day) => get(day, 'actual_worked_intervals', []).length > 0)
	.map((day) => day.work_date)
	.toSorted((left, right) => (left < right ? -1 : 1));
let streak = 0;
let longest = 0;
let previous = '';
for (const date of dates) {
	streak = previous !== '' && add_days(previous, 1) === date ? streak + 1 : 1;
	longest = Math.max(longest, streak);
	previous = date;
}
if (longest < ctx.lookup.consecutive_days) return false;
return get(ctx, 'reads.obligation', []).length === 0;

