	category === 'NON_MANUAL'
		? get(ctx.lookup, 'nonmanual_monthly_ceiling', 0)
		: get(ctx.lookup, 'manual_monthly_ceiling', 0);
if (!(Number(get(terms, 'rate.amount', 0)) <= ceiling)) return false;
const engagements = get(ctx.lookup, 'covered_engagements', null);
if (engagements === null) return true;
return engagements.includes(get(get(ctx, 'subject', {}), 'employment.engagement', ''));

ROSTER_CONSECUTIVE_HOURS.validate:
const intervals = get(ctx.entry, 'actual_worked_intervals', []);
return intervals.every(
	(interval) =>
		elapsed_minutes(interval.start, interval.end) <=
			get(ctx.lookup, 'consecutive_hours', 6) * 60 ||
		sum(
			get(interval, 'breaks', []).map((pause) => elapsed_minutes(pause.start, pause.end))
		) >=
			get(ctx.lookup, 'meal_break_minutes', 45)
);

ROSTER_YOUNG_NIGHT_WORK.condition:
const born = get(get(ctx, 'subject', {}), 'employment.payroll.date_of_birth', null);
const date = get(ctx.entry, 'work_date', null);
if (born === null || date === null) return false;
const manual = get(ctx.lookup, 'manual_categories', []).includes(
	get(get(get(ctx, 'subject', {}), 'employment.terms', {}), 'statutory_work_category', '')
);
return manual && age_on(String(born), String(date)) < get(ctx.lookup, 'young_age', 16);

ROSTER_YOUNG_NIGHT_WORK.validate:
const intervals = get(ctx.entry, 'actual_worked_intervals', []);
return (
	clock_window_minutes(
		intervals,
		get(ctx.subject.employer, 'time_zone', 'Asia/Singapore'),
		'23:00',
		'06:00'
	) === 0
);

