ROSTER_YOUNG_DAILY_HOURS.validate:
const elapsed =
	interval_minutes(get(ctx.entry, 'actual_worked_intervals', [])) / 60;
const born = String(get(get(ctx, 'subject', {}), 'employment.payroll.date_of_birth', ''));
const date = String(get(ctx.entry, 'work_date', ''));
if (born === '' || date === '') return true;
const age = age_on(born, date);
const limit =
	age < get(ctx.lookup, 'child_age', 15)
		? get(ctx.lookup, 'child_hours', 6)
		: get(ctx.lookup, 'young_hours', 7);
return elapsed <= limit;

ROSTER_YOUNG_REST_DAY.condition:
const born = get(get(ctx, 'subject', {}), 'employment.payroll.date_of_birth', null);
