ROSTER_YOUNG_BREAK.validate:
const born = String(get(get(ctx, 'subject', {}), 'employment.payroll.date_of_birth', ''));
const date = String(get(ctx.entry, 'work_date', ''));
if (born === '' || date === '') return true;
const age = age_on(born, date);
const limit =
	age < get(ctx.lookup, 'child_age', 15)
		? get(ctx.lookup, 'child_continuous_hours', 3)
		: get(ctx.lookup, 'young_continuous_hours', 4);
return get(ctx.entry, 'actual_worked_intervals', []).every(
	(interval) =>
		elapsed_minutes(interval.start, interval.end) <= limit * 60 ||
		sum(
			get(interval, 'breaks', []).map((pause) => elapsed_minutes(pause.start, pause.end))
		) >=
			get(ctx.lookup, 'break_minutes', 30)
);

CONTRACT_CATEGORIES.validate:
const terms = get(ctx.entry, 'terms', {});
if (!get(ctx.lookup, 'residency_statuses', []).includes(get(terms, 'residency_status', ''))) return false;
const pass = get(terms, 'work_authorisation_category', '');
if (pass !== '' && !get(ctx.lookup, 'work_pass_categories', []).includes(pass)) return false;
const classification = get(terms, 'work_classification', '');
if (!(classification === '' || get(ctx.lookup, 'work_classifications', []).includes(classification))) return false;
const category = get(terms, 'statutory_work_category', '');
return category === '' || get(ctx.lookup, 'statutory_work_categories', []).includes(category);

RESIDENCY_SINCE_REQUIRED.validate:
const terms = get(ctx.entry, 'terms', {});
return (
	get(terms, 'residency_status', '') !== 'PERMANENT_RESIDENT' ||
	get(get(ctx.entry, 'employee_extension_data', {}), 'residency_since', '') !== ''
);

SHARED_STRUCTURED_EMPLOYEE_INPUTS.validate:
const terms = get(ctx.entry, 'terms', {});
const extension = get(ctx.entry, 'employee_extension_data', {});
const limits = get(ctx.lookup, 'terms', {});
return Object.keys(limits).every((key) => {
	const rule = limits[key];
	const value = get(terms, key, get(extension, key, null));
	if (value == null) return get(rule, 'required', false) !== true;
	const number = Number(value);
	if (get(rule, 'integer', false) === true && number !== Math.trunc(number)) return false;
	const floor = get(rule, 'exclusive_minimum', null);
	if (floor !== null && !(number > floor)) return false;
	const minimum = get(rule, 'minimum', null);
	if (minimum !== null && !(number >= minimum)) return false;
	const maximum = get(rule, 'maximum', null);
	return maximum === null || number <= maximum;
});

SHARED_STRUCTURED_ENTITY_INPUTS.validate:
const extension = get(ctx.entry, 'entity_extension_data', {});
const limits = get(ctx.lookup, 'entity', {});
return Object.keys(limits).every((key) => {
	const rule = limits[key];
	const value = get(extension, key, null);
	if (value == null) return get(rule, 'required', false) !== true;
	if (typeof value === 'string') return value !== '';
	const number = Number(value);
	if (get(rule, 'integer', false) === true && number !== Math.trunc(number)) return false;
	const floor = get(rule, 'exclusive_minimum', null);
	if (floor !== null && !(number > floor)) return false;
	const maximum = get(rule, 'maximum', null);
	return maximum === null || number <= maximum;
});

DEPARTURE_CASE_ACTUAL_SCHEDULE.validate:
const scheduled = get(ctx.entry, 'scheduled_on', null);
if (scheduled == null || scheduled === '') return false;
const expected = get(get(ctx.entry, 'inputs', {}), 'expected_return_on', null);
if (expected == null || expected === '') return true;
return String(expected) >= String(scheduled);

SICK_WITHIN_HOSPITALISATION.validate:
// Employment Act s.89(1): the 60 days of hospitalisation leave include the 14 days of outpatient sick leave.
const shared = ctx.reads.leave_catalog;
const item = shared.find((row) => row.code === ctx.entry.catalog_code);
if (item == null) return true;
const slots = get(ctx.entry, 'leave_catalog_entry_day', []);
const year = String(slots[0].incurred_on).slice(0, 4);
const codes = shared.map((row) => row.code);
const within = (held) => held.filter((slot) => String(slot.incurred_on).slice(0, 4) === year).length / 2;
const grouped = group_by(ctx.reads.leave_catalog_entry_day, 'leave_entry_id');
const taken = ctx.reads.leave_catalog_entry
	.filter((row) => codes.includes(row.catalog_code))
	.reduce((total, row) => total + within(get(grouped, row.id, [])), 0);
const wanted = within(slots);
const hospital = shared.find((row) => row.code === ctx.lookup.hospitalisation);
const months = calendar_completed_months(String(ctx.subject.employment.effective_range.from), String(slots[0].incurred_on));
const cap = get(hospital.lookup, 'service_bands', []).filter((band) => band.service_months <= months).reduce((best, band) => Math.max(best, band.days), 0);
if (taken + wanted > cap) throw 'Sick and hospitalisation leave together would pass the ' + cap + ' days the year allows.';
return true;

ANNUAL_LEAVE.payout:
const terms = ctx.subject.employment.terms;
const basic = ctx.month_wage;
if (get(terms, 'rate.unit', 'MONTHLY') !== 'MONTHLY' || !(basic > 0)) return ctx.day_rate * ctx.entry.quantity;
// MOM gross rate of pay for salary in lieu of annual leave: the basic day with the fixed allowance on it
const allowance = get(terms, 'allowances.FIXED_MONTHLY.amount', 0);
const fixed = typeof allowance === 'number' ? allowance : get(allowance, 'value', 0);
return ctx.day_rate * ((basic + fixed) / basic) * ctx.entry.quantity;

lookup.entitlement:
// CDCSA s.12B, EA s.87A (MOM, Childcare leave): 6 days a year while a child is under 7 in the year,
// else 2 days of extended childcare leave while the youngest is 7 to 12; from 3 months' service,
// a first year prorated by completed months (service_bands), never below the 2 days the EA gives.
const employment = ctx.subject.employment;
const yearStart = String(ctx.as_of).slice(0, 4) + '-01-01';
const ages = get(employment, 'family', [])
	.filter((member) => member.relation === 'CHILD' && get(member, 'born_on', null) != null && member.born_on <= ctx.as_of)
	.map((member) => (member.born_on > yearStart ? 0 : age_on(member.born_on, yearStart)));
const youngest = ages.length === 0 ? null : Math.min(...ages);
if (youngest === null || youngest > 12) return 0;
const start = get(employment, 'service_started_on', get(employment, 'effective_range.from', ctx.as_of));
const months = calendar_completed_months(start, ctx.as_of);
const bands = ctx.lookup.service_bands.filter((band) => band.service_months <= months);
if (bands.length === 0) return 0;
const full = youngest < ctx.lookup.child_age_limit_years ? 6 : 2;
return Math.min(full, Math.max(2, bands[bands.length - 1].days));

// Child leave is a shared pool: 10 weeks from 1 April 2026, 6 weeks before. Each parent defaults to half;
// an HR-approved transfer is the child's own allocation under the leave catalogue code.
const birth = String(get(ctx, 'event.on', ctx.as_of));
const allocated = get(get(ctx.subject.employment, 'family', []).find((member) => member.relation === 'CHILD' && get(member, 'born_on', null) === birth), 'allocations.SHARED_PARENTAL_LEAVE', null);
if (allocated != null) return Number(allocated);
return (birth >= '2026-04-01' ? 70 : 42) / 2;

// Employment (Part-Time Employees) Regulations reg.7(1): the similar full-time annual leave under EA s.88A in proportion to the part-timer's weekly hours; reg.2(2) deems that employee to work 8 hours a day and 44 hours a week.
const employment = ctx.subject.employment;
const terms = get(employment, 'terms', {});
const weekly = Number(get(terms, 'normal_hours_per_week', 0));
const stated = Number(get(terms, 'normal_hours_per_day', 0));
const daysPerWeek = Number(get(terms, 'normal_days_per_week', 0));
const day = stated > 0 ? stated : daysPerWeek > 0 ? weekly / daysPerWeek : 0;
if (!(weekly > 0) || !(day > 0)) return 0;
const start = get(employment, 'service_started_on', get(employment, 'effective_range.from', ctx.as_of));
const months = calendar_completed_months(start, ctx.as_of);
if (months < ctx.lookup.eligibility_months) return 0;
const bands = ctx.lookup.service_bands;
const firstBand = bands[0];
const at = bands.filter((band) => band.service_months <= months);
let full = 0;
if (months < firstBand.service_months) full = (ctx.lookup.first_year_days * calendar_completed_months(start, add_days(ctx.as_of, 1))) / firstBand.service_months;
else if (at.length > 0) full = at[at.length - 1].days;
if (!(full > 0)) return 0;
// reg.2(2): the similar full-time employee's own hours; 8 a day and 44 a week only where there is none
const facts = get(employment, 'employee_extension_data', {});
const fullWeek = Number(get(facts, 'comparable_full_time_hours_per_week', ctx.lookup.full_time_weekly_hours));
const fullDay = Number(
	get(facts, 'comparable_full_time_hours_per_day', ctx.lookup.full_time_weekly_hours / ctx.lookup.full_time_days_per_week)
);
return Math.ceil(full * (weekly / fullWeek) * (fullDay / day) * 2) / 2;

ANNUAL_LEAVE_PART_TIME.payout:
// Employment (Part-Time Employees) Regulations reg.7(2): EA s.88A(8) pays annual leave not taken on dismissal otherwise than for misconduct at the part-timer's hourly gross rate; a day is the part-timer's own normal hours.
